581	 *  values are already placeholdered, so two passes of a lane that differed only
582	 *  in server-minted ids carry identical `behavior`. */
583	export type WitnessReactCypressRwaMeasuredPass = {
584		lane: 'baseline' | 'migrated';
585		pass: 1 | 2;
586		status: 'passed';
587		behavior: WitnessReactCypressRwaMeasuredBehavior;
588		/** The declared, legitimately per-lane presentation fact kept OUT of the
589		 *  shared behavior digest: the lane's own production-bundle byte identity. */
590		presentation: { laneStaticFiles: number; laneStaticDigest: string };
591		placeholders: readonly WitnessJourneyPlaceholderDeclaration[];
592	};
593	
594	/** The lane-independent behavior digest — the shared-parity projection. Two lanes
595	 *  reaching this same value is the parity guarantee. The per-lane byte identity is
596	 *  excluded by construction, so a different bundler cannot break parity, but a
597	 *  dropped leg, a re-pointed route, a console error, or a changed backend category
598	 *  will. */
599	export function witnessReactCypressRwaMeasuredBehaviorDigest(
600		pass: WitnessReactCypressRwaMeasuredPass,
601	): string {
602		return sha256(canonicalize(pass.behavior));
603	}
604	
605	/** The per-lane, pass-independent semantic digest — behavior folded together with
606	 *  the lane's own byte identity. Equal across a lane's two passes is the
607	 *  determinism guarantee; unequal across the two lanes is what proves the two
608	 *  behaviorDigests were reached by two genuinely distinct builds. */
609	export function witnessReactCypressRwaMeasuredSemanticDigest(
610		pass: WitnessReactCypressRwaMeasuredPass,
611	): string {
612		return sha256(canonicalize({ behavior: pass.behavior, presentation: pass.presentation }));
613	}
614	
615	export type WitnessReactCypressRwaLaneParity = {
616		lane: 'baseline' | 'migrated';
617		semanticDigest: string;
618		behaviorDigest: string;
619		legs: { ok: number; total: number };
620		deterministic: true;
621	};
622	
623	/** The full two-lane parity + pass-twice determinism verdict over the four
624	 *  measured passes (baseline×2, migrated×2). */
625	export type WitnessReactCypressRwaTwoLaneParity = {
626		result: 'parity';
627		behaviorDigest: string;
628		lanes: { baseline: WitnessReactCypressRwaLaneParity; migrated: WitnessReactCypressRwaLaneParity };
629		behaviorParity: true;
630		lanesAreDistinctBuilds: true;
631	};
632	
633	function assertMeasuredPassClean(pass: WitnessReactCypressRwaMeasuredPass, label: string): void {
634		const b = pass.behavior;
635		if (
636			pass.status !== 'passed' ||
637			b.legs.total < 1 ||
638			b.legs.ok !== b.legs.total ||
639			b.consoleErrors !== 0 ||
640			b.pageErrors !== 0 ||
641			b.failedRequests !== 0 ||
642			b.successfulNonLoopback !== 0 ||
643			!Array.isArray(b.navigations) ||
644			b.navigations.length === 0 ||
645			!Array.isArray(b.backend) ||
646			b.backend.length === 0 ||
647			!Number.isInteger(pass.presentation.laneStaticFiles) ||
648			pass.presentation.laneStaticFiles < 1 ||
649			!sha256Digest(pass.presentation.laneStaticDigest) ||
650			!exact(pass.placeholders, WITNESS_REACT_CYPRESS_RWA_PLACEHOLDERS)
651		)
652			throw new Error(`Cypress RWA calibration pass is not clean: ${label}`);
653		const declared = new Set(
654			WITNESS_REACT_CYPRESS_RWA_BACKEND_CATEGORY.map((entry) => `${entry.method} ${entry.path}`),
655		);
656		for (const observation of b.backend)
657			if (!declared.has(`${observation.method} ${observation.path}`))
658				throw new Error(`Cypress RWA calibration backend observation is undeclared: ${label}`);
659		const strings: string[] = [];
660		collectStrings(pass, strings);
661		for (const text of strings)
662			for (const marker of WITNESS_REACT_CYPRESS_RWA_FORBIDDEN_MARKERS)
663				if (text.includes(marker))
664					throw new Error(`Cypress RWA calibration redaction leaked a seed marker: ${label}`);
665	}
666	
667	/**
668	 * The gate: given the four measured passes, prove two-lane parity and pass-twice
669	 * determinism, or throw with the specific violation. Enforced facts:
670	 *
671	 *   - exactly the four passes baseline:1, baseline:2, migrated:1, migrated:2;
672	 *   - each pass clean (all legs ok, 0 console/page/failed, successfulNonLoopback
673	 *     0, backend inside the declared category, no seed marker);
674	 *   - pass-1 semanticDigest == pass-2 semanticDigest on EACH lane (determinism);
675	 *   - a single behaviorDigest across all four passes (two-lane parity);
676	 *   - the two lanes' semanticDigests DIFFER (parity is over distinct builds).
677	 */
678	export function summarizeWitnessReactCypressRwaTwoLaneParity(
679		passes: readonly WitnessReactCypressRwaMeasuredPass[],
680	): WitnessReactCypressRwaTwoLaneParity {
681		const expected = new Set(['baseline:1', 'baseline:2', 'migrated:1', 'migrated:2']);
682		const semanticByLane = new Map<'baseline' | 'migrated', Map<1 | 2, string>>([
683			['baseline', new Map()],
684			['migrated', new Map()],
685		]);
686		const behaviors = new Set<string>();
687		for (const pass of passes) {
688			const key = `${pass.lane}:${pass.pass}`;
689			if (!expected.delete(key))
690				throw new Error(`Cypress RWA calibration pass is unexpected or duplicated: ${key}`);
691			assertMeasuredPassClean(pass, key);
692			semanticByLane.get(pass.lane)!.set(pass.pass, witnessReactCypressRwaMeasuredSemanticDigest(pass));
693			behaviors.add(witnessReactCypressRwaMeasuredBehaviorDigest(pass));
694		}
695		if (expected.size !== 0)
696			throw new Error(`Cypress RWA calibration is missing passes: ${[...expected].join(', ')}`);
697		// Pass-twice determinism is checked per lane FIRST, so a within-lane drift
698		// surfaces as the determinism failure it is rather than as a parity break.
699		const lane = (name: 'baseline' | 'migrated'): WitnessReactCypressRwaLaneParity => {
700			const byPass = semanticByLane.get(name)!;
701			const one = byPass.get(1);
702			const two = byPass.get(2);
703			if (one === undefined || two === undefined)
704				throw new Error(`Cypress RWA calibration lane is missing a pass: ${name}`);
705			if (one !== two)
706				throw new Error(`Cypress RWA calibration pass-twice semantic digest drifted: ${name}`);
707			const first = passes.find((pass) => pass.lane === name && pass.pass === 1)!;
708			return {
709				lane: name,
710				semanticDigest: one,
711				behaviorDigest: witnessReactCypressRwaMeasuredBehaviorDigest(first),
712				legs: first.behavior.legs,
713				deterministic: true,
714			};
715		};
716		const baseline = lane('baseline');
717		const migrated = lane('migrated');
718		// Two-lane behavior parity: after each lane is internally deterministic, the
719		// two lanes must share the one behavior digest.
720		if (behaviors.size !== 1)
721			throw new Error('Cypress RWA calibration lanes did not reach one behavior digest (parity)');
722		const [behaviorDigest] = [...behaviors];
723		if (baseline.semanticDigest === migrated.semanticDigest)
724			throw new Error('Cypress RWA calibration lanes are byte-identical, so parity is trivial');
725		return {
726			result: 'parity',
727			behaviorDigest: behaviorDigest!,
728			lanes: { baseline, migrated },
729			behaviorParity: true,
730			lanesAreDistinctBuilds: true,
731		};
732	}
