224			throw new Error(`Cypress RWA holdout ${label} must be an object`);
225		return value as Record<string, unknown>;
226	}
227	
228	function array(value: unknown, label: string): unknown[] {
229		if (!Array.isArray(value)) throw new Error(`Cypress RWA holdout ${label} must be an array`);
230		return value;
231	}
232	
233	function text(value: unknown, label: string): string {
234		if (typeof value !== 'string' || value.length === 0)
235			throw new Error(`Cypress RWA holdout ${label} must be a non-empty string`);
236		return value;
237	}
238	
239	function count(value: unknown, label: string): number {
240		if (typeof value !== 'number' || !Number.isInteger(value) || value < 0)
241			throw new Error(`Cypress RWA holdout ${label} must be a non-negative integer`);
242		return value;
243	}
244	
245	function flag(value: unknown, label: string): boolean {
246		if (typeof value !== 'boolean') throw new Error(`Cypress RWA holdout ${label} must be boolean`);
247		return value;
248	}
