549	export function parseHoldoutReactCypressRwaReceipt(value: unknown): HoldoutReactCypressRwaReceipt {
550		const receipt = record(value, 'receipt') as unknown as HoldoutReactCypressRwaReceipt;
551		if (
552			receipt.schemaVersion !== HOLDOUT_REACT_CYPRESS_RWA_SCHEMA ||
553			receipt.role !== 'holdout' ||
554			receipt.holdoutOutcome !== 'failed' ||
555			receipt.reason !== HOLDOUT_REACT_CYPRESS_RWA_MISSING_CAPABILITY ||
556			receipt.unit !== HOLDOUT_REACT_CYPRESS_RWA_UNIT ||
557			receipt.fixture !== HOLDOUT_REACT_CYPRESS_RWA_FIXTURE ||
558			receipt.application !== HOLDOUT_REACT_CYPRESS_RWA_APPLICATION ||
559			receipt.framework !== 'react'
560		)
561			throw new Error('Cypress RWA holdout identity differs');
562		if (
563			receipt.frozenAdapter?.compositeFingerprint !==
564				HOLDOUT_REACT_CYPRESS_RWA_FROZEN_FINGERPRINT ||
565			receipt.frozenAdapter.bytesChanged !== 0 ||
566			receipt.frozenAdapter.changesProposedAndExecuted !== 0 ||
567			receipt.frozenAdapter.redBuildPatchedAround !== false ||
568			receipt.frozenAdapter.recomputedByThisUnit !== true ||
569			receipt.frozenAdapter.subtrees.length !== 5
570		)
571			throw new Error('Cypress RWA holdout freeze binding differs');
572		if (
573			receipt.lanes?.baseline?.outcome !== 'green' ||
574			receipt.lanes.baseline.builds !== 2 ||
575			receipt.lanes.baseline.byteStableAcrossRebuilds !== true ||
576			receipt.lanes.baseline.laneDigest !== receipt.lanes.baseline.secondLaneDigest ||
577			!sha256Hex.test(receipt.lanes.baseline.laneDigest) ||
578			receipt.lanes.migrated?.outcome !== 'red' ||
579			receipt.lanes.migrated.attempts !== 2 ||
580			receipt.lanes.migrated.stableAcrossAttempts !== true ||
581			receipt.lanes.migrated.outputProduced !== false ||
582			receipt.lanes.migrated.demands.length === 0
583		)
584			throw new Error('Cypress RWA holdout lane evidence differs');
585		if (
586			receipt.identityProof?.baselineAttempts !== 2 ||
587			receipt.identityProof.migratedAttempts !== 2 ||
588			receipt.identityProof.baselineDigestsIdentical !== true ||
589			receipt.identityProof.migratedDemandsIdentical !== true ||
590			receipt.identityProof.demandDigest !== sha256(canonicalize(receipt.lanes.migrated.demands))
591		)
592			throw new Error('Cypress RWA holdout two-attempt identity proof differs');
593		if (
594			receipt.finding?.missingCapability !== HOLDOUT_REACT_CYPRESS_RWA_MISSING_CAPABILITY ||
595			receipt.finding.offendingFile.invalidUtf8ByteCount !== 6 ||
596			receipt.finding.offendingFile.invalidBytes.length === 0 ||
597			!sha256Hex.test(receipt.finding.offendingFile.sha256) ||
598			receipt.applicationInfluence?.applicationFilesChanged !== 0 ||
599			receipt.applicationInfluence.adapterBytesChanged !== 0 ||
600			receipt.applicationInfluence.handEditedSourceFiles.length !== 0 ||
601			receipt.parity?.comparable !== false ||
602			!Array.isArray(receipt.nonclaims) ||
603			!HOLDOUT_REACT_CYPRESS_RWA_ADDED_NONCLAIMS.every((claim) =>
604				receipt.nonclaims.includes(claim),
605			)
606		)
607			throw new Error('Cypress RWA holdout finding or non-claims differ');
608		if (
609			receipt.integrity?.algorithm !== 'sha256' ||
610			!sha256Hex.test(receipt.integrity.canonicalDigest) ||
611			receipt.integrity.canonicalDigest !== holdoutReactCypressRwaDigest(receipt)
612		)
613			throw new Error('Cypress RWA holdout integrity differs');
614		return receipt;
615	}
