617	export function renderHoldoutReactCypressRwaReceipt(
618		receipt: HoldoutReactCypressRwaReceipt,
619	): string {
620		const demand = receipt.finding.exactDemand;
621		const offending = receipt.finding.offendingFile;
622		const bytes = offending.invalidBytes
623			.map((entry) => `${entry.byte} at offset ${entry.offset} (\`${entry.inWord}\`)`)
624			.join(', ');
625		return `# cypress-realworld-app — holdout falsification receipt
626	
627	- Outcome: **${receipt.holdoutOutcome}** — the frozen adapter does not carry this application at this revision
628	- Recorded reason: missing generic capability — **${receipt.reason}**
629	- Canonical SHA-256: ${receipt.integrity.canonicalDigest}
630	- Unit: \`${receipt.unit}\`
631	- Source: ${receipt.source.repository} at \`${receipt.source.ref}\` (\`${receipt.source.revision}\`, ${receipt.source.license}), create-react-app ${receipt.source.reactScripts} over webpack ${receipt.source.webpack}, React ${receipt.source.react}, TypeScript ${receipt.source.typescript}
632	- Frozen adapter fingerprint: \`${receipt.frozenAdapter.compositeFingerprint}\` over ${receipt.frozenAdapter.subtrees.length} subtrees, recomputed by this unit; adapter bytes changed: ${receipt.frozenAdapter.bytesChanged}; adapter changes proposed and executed: ${receipt.frozenAdapter.changesProposedAndExecuted}
633	- Derived from committed run evidence: ${receipt.runEvidence.map((item) => `\`${item.path}\` (\`${item.sha256}\`)`).join(', ')}
634	
635	## Both lanes
636	
637	- Shared closure: ${receipt.lanes.sharedClosure.statement}
638	- Baseline (${receipt.lanes.baseline.command}, Node ${receipt.lanes.baseline.node} declared by ${receipt.lanes.baseline.declaredBy.join(' and ')}): **${receipt.lanes.baseline.outcome}**, built ${receipt.lanes.baseline.builds}x byte-stable, ${receipt.lanes.baseline.fileCount} files, lane digest \`${receipt.lanes.baseline.laneDigest}\` under ${receipt.lanes.baseline.digestScheme}
639	- Migrated (${receipt.lanes.migrated.command}, Node ${receipt.lanes.migrated.node}, Vite ${receipt.lanes.migrated.vite}, ${receipt.lanes.migrated.bundler}): **${receipt.lanes.migrated.outcome}**, ${receipt.lanes.migrated.attempts} attempts, exit ${receipt.lanes.migrated.exitCode} after ${receipt.lanes.migrated.modulesTransformedBeforeFailure} transformed modules, no output produced
640	- Two-attempt identity proof: ${receipt.identityProof.statement} Demand multiset digest \`${receipt.identityProof.demandDigest}\`.
641	
642	## The finding
643	
644	**Missing capability: ${receipt.finding.missingCapability}.**
645	
646	${receipt.finding.statement}
647	
648	- Exact demand: \`${demand.code}\` loading \`${demand.module}\` from \`${demand.importer}\`:${demand.line}:${demand.column} — ${demand.compilerText}
649	- Offending file: \`${offending.path}\` (${offending.package}, ${offending.bytes} bytes, sha256 \`${offending.sha256}\`), stored in ${offending.encoding}, ${offending.invalidUtf8ByteCount} invalid UTF-8 bytes: ${bytes}. ${offending.invalidBytesNote}
650	- Reached from production application code: \`${receipt.finding.reachedFromApplicationCode.importer}\` does \`${receipt.finding.reachedFromApplicationCode.construct}\` — ${receipt.finding.reachedFromApplicationCode.note}
651	- Why this is not an adapter bug: ${receipt.finding.whyThisIsNotAnAdapterBug}
652	- Action taken: ${receipt.finding.actionTaken}
653	
654	## Zero influence
655	
656	${receipt.applicationInfluence.attestation} Application files changed: ${receipt.applicationInfluence.applicationFilesChanged}. Generated by the application's own scripts: ${receipt.applicationInfluence.generatedByTheApplicationsOwnScripts.map((item) => `\`${item.path}\``).join(', ')}; generated by the migration: ${receipt.applicationInfluence.generatedByTheMigration.map((item) => `\`${item.path}\``).join(', ')}.
657	
658	Observed but not fatal: ${receipt.observedButNotFatal.externalizedNodeCoreModules.map((item) => `\`${item.module}\` for \`${item.importer}\``).join(', ')}. ${receipt.observedButNotFatal.note}
659	
660	## Parity and non-claims
661	
662	${receipt.parity.reason}
663	
664	${receipt.nonclaims.map((claim) => `- ${claim}`).join('\n')}
665	`;
666	}
